import { useState, useEffect } from 'react';
import { MOCK_PRODUCTS } from '../data/products';

// Маппінг даних з fakestoreapi до формату нашого магазину
const mapApiProduct = (p) => ({
  id: p.id,
  title: p.title,
  price: Math.round(p.price * 40), // конвертація USD → UAH (приблизно)
  category: p.category,
  description: p.description,
  image: p.image,
  rating: p.rating,
});

export function useProducts() {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError]     = useState(null);

  useEffect(() => {
    let cancelled = false;

    const fetchProducts = async () => {
      setLoading(true);
      setError(null);
      try {
        const res = await fetch('https://fakestoreapi.com/products?limit=20');
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const data = await res.json();
        if (!cancelled) setProducts(data.map(mapApiProduct));
      } catch (err) {
        // Якщо API недоступний — використовуємо моковані дані
        console.warn('API недоступний, використовуємо fallback дані:', err.message);
        if (!cancelled) {
          setProducts(MOCK_PRODUCTS);
          setError('offline'); // спеціальний маркер — не помилка, а режим офлайн
        }
      } finally {
        if (!cancelled) setLoading(false);
      }
    };

    fetchProducts();
    return () => { cancelled = true; };
  }, []);

  return { products, loading, error };
}

export function useProduct(id) {
  const [product, setProduct] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError]     = useState(null);

  useEffect(() => {
    if (!id) return;
    let cancelled = false;

    const fetchProduct = async () => {
      setLoading(true);
      try {
        const res = await fetch(`https://fakestoreapi.com/products/${id}`);
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const data = await res.json();
        if (!cancelled) setProduct(mapApiProduct(data));
      } catch {
        // Fallback до мокових даних
        const mock = MOCK_PRODUCTS.find(p => p.id === Number(id));
        if (!cancelled) {
          setProduct(mock || null);
          if (!mock) setError('Товар не знайдено');
        }
      } finally {
        if (!cancelled) setLoading(false);
      }
    };

    fetchProduct();
    return () => { cancelled = true; };
  }, [id]);

  return { product, loading, error };
}
